import Foundation
import Testing
import SwiftUI
import UIKit
@testable import Oriveo

/// Phosphor assets are generated by scripts/phosphor-icons.mjs; a misspelled `Image("…")` only shows up as a blank at runtime,
/// so each icon is actually loaded once from the app bundle.
@Suite("PhosphorIcon: generated assets load from the bundle")
struct PhosphorIconAssetTests {

    @Test("every icon in the manifest loads in both the regular and duotone weights, rendered as a template")
    func everyIconLoadsAsTemplate() {
        // The expected count is read from the single shared manifest so adding an icon needs no edit here; if the manifest cannot be found, fall back to the currently registered count
        #expect(PhosphorIcon.allCases.count == (Self.manifestIconCount() ?? 58))
        for icon in PhosphorIcon.allCases {
            for weight in PhosphorIcon.Weight.allCases {
                let name = icon.assetName(weight)
                let image = UIImage(named: name, in: .main, compatibleWith: nil)
                #expect(image != nil, "\(name) is missing from Assets.car")
                #expect(image?.renderingMode == .alwaysTemplate, "\(name) is not template-rendered, so tinting would not work")
            }
        }
    }

    @Test("the five capability palette colors: dark mode uses the 400 shade and light mode the 600 shade")
    func capabilityPaletteResolvesPerColorScheme() {
        let expected: [(Color, light: UInt, dark: UInt)] = [
            (CapabilityPalette.webSearch, 0x2563EB, 0x60A5FA),
            (CapabilityPalette.reasoning, 0x7C3AED, 0xA78BFA),
            (CapabilityPalette.attachment, 0xD97706, 0xFBBF24),
            (CapabilityPalette.vision, 0x059669, 0x34D399),
            (CapabilityPalette.tools, 0xDB2777, 0xF472B6),
        ]
        for (color, light, dark) in expected {
            #expect(hex(color, scheme: .light) == light)
            #expect(hex(color, scheme: .dark) == dark)
        }
    }

    /// Walk up from #filePath to find shared/icons/phosphor/manifest.json and return the length of its icons array
    private static func manifestIconCount() -> Int? {
        struct Manifest: Decodable { let icons: [Icon] }
        struct Icon: Decodable { let name: String }
        var cursor = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        while cursor.path != "/" {
            let candidate = cursor
                .appendingPathComponent("shared")
                .appendingPathComponent("icons")
                .appendingPathComponent("phosphor")
                .appendingPathComponent("manifest.json")
            if FileManager.default.fileExists(atPath: candidate.path) {
                guard let data = try? Data(contentsOf: candidate),
                      let manifest = try? JSONDecoder().decode(Manifest.self, from: data) else { return nil }
                return manifest.icons.count
            }
            cursor.deleteLastPathComponent()
        }
        return nil
    }

    private func hex(_ color: Color, scheme: ColorScheme) -> UInt {
        var environment = EnvironmentValues()
        environment.colorScheme = scheme
        let resolved = color.resolve(in: environment)
        let channel = { (value: Float) in UInt((max(0, min(1, value)) * 255).rounded()) }
        return channel(resolved.red) << 16 | channel(resolved.green) << 8 | channel(resolved.blue)
    }
}
